import {LOCAL_MODE,APP_ROOT,HOSTED_APP,assetURL,mediaURL} from './platform.js';
import {uid,clone,clamp,esc,object,page,project,starter,templates,assets,bounds,hit,History,diff,apply,validateProject} from './model.js';
import {Renderer,renderPage,drawObject,pageSVG,exportPDF,download,loadMedia,font} from './renderer.js';
import {Sync} from './sync.js';import {icon} from './icons.js';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
let doc=starter(),pageIndex=0,selected=[],panel='design',view='editor',zoom=1,autoFit=true,tool='select',gesture=null,editing=null,history=new History(),clipboard=[],renderFrame=0,thumbTimer=0,backend='Initializing',search='',category='All',notesOpen=false,presenting=false,remoteDeferred=null,people=[],user=null,projects=[],uploadList=[],gridView=false;
const state={mobilePanel:false,drawColor:'#7654e8',drawWidth:5,showGuides:false};
const pg=()=>doc.pages[pageIndex]||doc.pages[0];const chosen=()=>pg().objects.filter(o=>selected.includes(o.id));const one=()=>chosen()[0];
const btn=(action,label,ic='',cls='',extra='')=>`<button type="button" data-action="${action}" class="${cls}" ${extra}>${ic?icon(ic):''}${label?`<span>${label}</span>`:''}</button>`;
const ib=(action,ic,label,extra='')=>btn(action,'',ic,'icon-button',`title="${label}" aria-label="${label}" ${extra}`);
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3600)}
function status(text){if(LOCAL_MODE){if(text==='All changes saved')text='Saved on this device';if(text==='Saving…')text='Saving on this device…'}const e=$('#save-status');if(e)e.textContent=text;const b=$('#save-state');if(b)b.title=text}
const sync=new Sync(next=>{if(gesture||editing){remoteDeferred=next;return}doc=next;pageIndex=Math.min(pageIndex,doc.pages.length-1);selected=selected.filter(id=>pg().objects.some(o=>o.id===id));const title=$('#project-title');if(title&&document.activeElement!==title)title.value=doc.name;if(view==='editor'){draw();scheduleThumbs()}},status,p=>{people=p||[];renderPeople()});
function editable(){if(sync.role&& !['owner','edit'].includes(sync.role)){toast('This design is read only. Ask the owner for edit access.');return false}return true}
function transaction(fn){if(!editable())return;const before=clone(doc);try{fn();validateProject(doc);commit(before)}catch(e){doc=before;draw();toolbar();toast(e.message)}}
function commit(before){try{validateProject(doc)}catch(e){doc=before;gesture=null;editing=null;draw();toolbar();toast(e.message);return}const local=clone(doc);history.push(before,local);sync.queue(before,local);if(remoteDeferred){doc=apply(remoteDeferred,diff(before,local));remoteDeferred=null}if(!sync.id)status('Unsaved design');draw();toolbar();scheduleThumbs();if(['layers','position','brand'].includes(panel))renderPanel()}
function shell(){document.body.classList.toggle('theme-dark',localStorage.getItem('velora-theme')==='dark');$('#app').innerHTML=`<div class="app-shell"><header class="topbar">${btn('home','Velora','','logo', 'aria-label="Velora home"')}${btn('file','File','','quiet file-label')}${btn('resize','Resize', '','quiet resize-label')}${icon('down',12)}<span class="divider"></span>${ib('undo','undo','Undo (Ctrl+Z)')}${ib('redo','redo','Redo (Ctrl+Shift+Z)')}<input id="project-title" class="project-title" value="${esc(doc.name)}" aria-label="Design name"><div class="save-indicator" id="save-state" title="Connecting…">${icon('cloud',21)}<span id="save-status">Connecting…</span></div><div class="avatar-stack" id="avatars"><div class="avatar" title="You">${esc((user?.name||'You').slice(0,1).toUpperCase())}</div></div>${btn('present','Present','play','present-btn')}${btn('share','Share','share','share-btn')}</header><div class="workspace"><nav class="rail" aria-label="Design tools">${[['design','design','Design'],['elements','elements','Elements'],['text','text','Text'],['uploads','upload','Uploads'],['brand','brand','Brand'],['draw','draw','Draw'],['projects','folder','Projects']].map(([a,i,l])=>btn('panel:'+a,l,i,a===panel?'active':'')).join('')}<div class="bottom">${btn('help','Help','help')}</div></nav><aside class="panel" id="panel"></aside><main class="editor" id="editor"><div class="toolbar" id="toolbar"></div><div class="canvas-area" id="canvas-area"><div class="page-surround" id="page-surround"><div class="page-heading"><span id="page-label"></span><div class="page-actions">${ib('page-up','chevron','Previous page','style="transform:rotate(-90deg)"')}${ib('page-down','chevron','Next page','style="transform:rotate(90deg)"')}${ib('duplicate-page','copy','Duplicate page')}${ib('delete-page','trash','Delete page')}${ib('add-page','plus','Add page')}</div></div><div class="artboard" id="artboard"><canvas id="canvas"></canvas><div id="interaction" class="interaction" tabindex="0" role="application" aria-label="Design canvas. Select elements to move or resize. Double click text to edit."></div></div></div>${btn('comments','','comment','floating-comment','aria-label="Open comments"')}</div><div class="pages-strip" id="pages-strip"></div><footer class="statusbar">${btn('notes','Notes','note')}${btn('timing',doc.pages.reduce((a,p)=>a+(p.duration||5),0)+'s','clock','optional')}<span class="spacer"></span><span class="optional" id="page-count"></span><input id="zoom-slider" type="range" min="10" max="200" value="60" aria-label="Canvas zoom"><button data-action="fit" class="zoom-value" id="zoom-value">Fit</button>${ib('grid','grid','Page overview')}${ib('fullscreen','expand','Full screen')}${ib('diagnostics','help','Rendering information')}</footer></main></div></div>`;
window.renderer=new Renderer($('#canvas'),b=>{backend=b});renderPanel();toolbar();renderThumbs();bindCanvas();requestAnimationFrame(()=>{fit();draw()});new ResizeObserver(()=>{if(autoFit&&view==='editor')fit()}).observe($('#canvas-area'))}
function toolbar(){if(view!=='editor'||!$('#toolbar'))return;const o=one(),multiple=selected.length>1;let html='';if(!o){html=`<label class="color-control" title="Page color"><input type="color" data-prop="background" value="${pg().background||'#ffffff'}" aria-label="Page background"></label><span class="divider"></span>${btn('styles','Styles','sparkle')}${btn('add-text','Add text','text')}${btn('timing',(pg().duration||5)+'.0s','clock')}<span class="spacer"></span>${btn('layers','Layers','layers')}${btn('position','Position','','optional')}`}
else{html=`<label class="color-control" title="Element color"><input type="color" data-prop="fill" value="${/^#[\da-f]{6}$/i.test(o.fill||'')?o.fill:'#7654e8'}" aria-label="Element color"></label>`;if(o.type==='text')html+=`<select data-prop="fontFamily" aria-label="Font family">${['Arial','Georgia','Verdana','Trebuchet MS','Courier New','Times New Roman','DM Sans','Manrope'].map(f=>`<option ${o.fontFamily===f?'selected':''}>${f}</option>`).join('')}</select><input data-prop="fontSize" type="number" min="6" max="600" value="${o.fontSize||32}" aria-label="Font size">${ib('bold','bold','Bold',o.bold?'style="background:#e8dafa"':'')}${ib('italic','italic','Italic',o.italic?'style="background:#e8dafa"':'')}${ib('text-align','align','Text alignment')}`;else if(['image','video'].includes(o.type))html+=`${btn('photo-edit','Edit image','settings')}${btn('crop','Crop')}${btn('flip','Flip')}`;else if(o.type==='chart')html+=btn('chart-edit','Edit data','chart');else html+=`<span style="font-size:13px;text-transform:capitalize">${multiple?selected.length+' elements':o.type}</span>`;html+=`<span class="divider"></span>${btn('opacity','Transparency')}${btn('position','Position')}<span class="spacer"></span>${ib('duplicate','copy','Duplicate (Ctrl+D)')}${ib('lock',o.locked?'lock':'unlock','Lock or unlock')}${ib('delete','trash','Delete')}${ib('more','more','More element actions')}`}
$('#toolbar').innerHTML=html;$('#project-title').readOnly=sync.role&&!['owner','edit'].includes(sync.role)}
function fit(){const area=$('#canvas-area');if(!area)return;const r=area.getBoundingClientRect();zoom=clamp(Math.min((r.width-(innerWidth<700?30:90))/doc.width,(r.height-80)/doc.height),.08,1.2);layoutCanvas()}
function layoutCanvas(){const board=$('#artboard'),surround=$('#page-surround');if(!board)return;board.style.width=doc.width+'px';board.style.height=doc.height+'px';board.style.transform=`scale(${zoom})`;surround.style.width=doc.width*zoom+'px';surround.style.height=doc.height*zoom+'px';$('#zoom-value').textContent=Math.round(zoom*100)+'%';$('#zoom-slider').value=Math.round(zoom*100);draw()}
function draw(){if(view!=='editor'||!$('#canvas'))return;cancelAnimationFrame(renderFrame);renderFrame=requestAnimationFrame(()=>{window.renderer.render(pg(),doc.width,doc.height,zoom);overlay();$('#page-label').textContent=`Page ${pageIndex+1} · ${pg().name}`;$('#page-count').textContent=`${pageIndex+1} / ${doc.pages.length} pages`})}
function overlay(){const layer=$('#interaction');if(!layer)return;$$('.selection,.cursor,.snapline',layer).forEach(e=>e.remove());for(const o of chosen()){const el=document.createElement('div');el.className='selection';Object.assign(el.style,{left:o.x+'px',top:o.y+'px',width:o.w+'px',height:o.h+'px',transform:`rotate(${o.rotation||0}deg)`,borderWidth:(1.5/zoom)+'px'});el.dataset.id=o.id;if(selected.length===1&&!o.locked){el.innerHTML=['nw','n','ne','e','se','s','sw','w'].map(h=>`<span class="handle" data-handle="${h}" style="width:${8/zoom}px;height:${8/zoom}px"></span>`).join('')+`<span class="rotation-handle" data-handle="rotate" style="transform:translateX(-50%) scale(${1/zoom});transform-origin:top center">${icon('rotate',14)}</span>`}layer.append(el)}renderPeople()}
function renderPeople(){if(!$('#avatars'))return;const active=people.filter(p=>p.actor!==user?.id);$('#avatars').innerHTML=`<div class="avatar" title="${esc(user?.name||'You')}">${esc((user?.name||'Y')[0].toUpperCase())}</div>`+active.slice(0,3).map(p=>`<div class="avatar" title="${esc(p.name)}">${esc(p.name.slice(0,1).toUpperCase())}</div>`).join('');const layer=$('#interaction');if(!layer)return;$$('.cursor',layer).forEach(c=>c.remove());for(const p of active.filter(p=>p.page===pg().id)){const c=document.createElement('div');c.className='cursor';c.style.cssText=`left:${p.x}px;top:${p.y}px;transform:scale(${1/zoom});transform-origin:top left`;c.innerHTML=icon('arrow',18)+`<span><b>${esc(p.name)}</b></span>`;layer.append(c)}}
function scheduleThumbs(){clearTimeout(thumbTimer);thumbTimer=setTimeout(renderThumbs,250)}
function renderThumbs(){if(view!=='editor'||!$('#pages-strip'))return;$('#pages-strip').innerHTML=doc.pages.map((p,i)=>`<button class="page-thumb ${i===pageIndex?'active':''}" data-action="page:${i}" title="${esc(p.name)}" draggable="true" data-page-index="${i}"><canvas data-thumb="${i}"></canvas><span class="number">${i+1}</span></button>`).join('')+btn('add-page','','plus','add-page-thumb','aria-label="Add page"');$$('[data-thumb]').forEach(c=>renderPage(c,doc.pages[+c.dataset.thumb],doc.width,doc.height,220/doc.width))}
function panelHeading(title,extra=''){return `<div class="panel-title"><h2>${title}</h2>${extra||ib('close-panel','close','Close panel')}</div>`}
function renderPanel(){if(view!=='editor')return;const host=$('#panel');host.classList.toggle('mobile-open',state.mobilePanel);$$('.rail button').forEach(b=>b.classList.toggle('active',b.dataset.action==='panel:'+panel));let html='';
if(panel==='design'){html=panelHeading('Design')+`<div class="search">${icon('search',18)}<input id="template-search" placeholder="Search templates" value="${esc(search)}" aria-label="Search templates"></div><div class="tabs">${btn('templates-tab','Templates','','active')}${btn('styles','Styles')}</div><div class="chips">${['All','Presentations','Social media','Posters'].map(c=>btn('category:'+c,c,'','chip '+(category===c?'active':''))).join('')}</div><div class="section-heading">For you <small>Made for your next idea</small></div><div class="template-grid" id="template-grid"></div><div class="design-callout">${icon('sparkle',22)}<strong>A little inspiration, a lot of you.</strong><p>Start with a design. Make it your own.</p>${btn('explore','Explore all templates')}</div><div class="section-heading">Start from scratch</div>${btn('new-design','Create a blank design','plus','outline-button full')}<div class="panel-footer">Your ideas look good here.</div>`}
if(panel==='elements'){html=panelHeading('Elements')+`<div class="section-heading">Shapes & lines</div><div class="shape-grid">${[['rect','<rect x="3" y="3" width="38" height="38" rx="3" fill="currentColor"/>'],['ellipse','<circle cx="22" cy="22" r="20" fill="currentColor"/>'],['triangle','<path d="M22 2 43 41H1Z" fill="currentColor"/>'],['line','<path d="M2 22H42" stroke="currentColor" stroke-width="4"/>'],['arrow','<path d="M2 22H42M30 10l12 12-12 12" stroke="currentColor" stroke-width="3" fill="none"/>'],['chart','<path d="M5 39V23M19 39V13M33 39V3" stroke="currentColor" stroke-width="9"/>']].map(([k,v])=>`<button class="shape-item" data-action="shape:${k}" aria-label="Add ${k}"><svg viewBox="0 0 44 44">${v}</svg></button>`).join('')}</div><div class="section-heading">Photos <small>Original collection</small></div><div class="photo-grid">${assets.map((a,i)=>`<button data-action="photo:${i}" title="${esc(a.name)}"><img src="${assetURL(a.src)}" alt="${esc(a.name)}"></button>`).join('')}</div><div class="section-heading" style="margin-top:25px">Frames</div><div class="shape-grid">${btn('frame:round','Rounded')}${btn('frame:circle','Circle')}${btn('frame:square','Square')}</div><p class="empty" style="padding:10px">Select any shape to change its color, size, or position.</p>`}
if(panel==='text'){html=panelHeading('Text')+btn('add-text','Add a text box','plus','primary-button full')+`<div class="section-heading" style="margin-top:26px">Default text styles</div><div class="text-presets">${btn('text:heading','Add a heading','','text-preset heading')}${btn('text:subheading','Add a subheading','','text-preset subheading')}${btn('text:body','Add a little body text','','text-preset body')}</div><div class="section-heading" style="margin-top:27px">Font pairings</div><button class="text-preset full" data-action="text:pair" style="flex-direction:column;background:#f1eadf;color:#323f32"><span style="font:italic 32px Georgia">The good things.</span><span style="font-size:10px;letter-spacing:2px;margin-top:5px">ARE THE SIMPLE THINGS</span></button><button class="text-preset full" data-action="text:bold-pair" style="margin-top:13px;background:#e9e0fc;color:#7250a5;flex-direction:column"><span style="font:700 30px Arial">MAKE IT</span><span style="font:italic 31px Georgia">happen.</span></button>`}
if(panel==='uploads'){html=panelHeading('Uploads')+btn('upload','Upload files','upload','primary-button full')+`<div class="upload-zone" id="upload-zone">${icon('upload',29)}<p>Drag files here, or choose a file.<br>Images, video, and audio · up to 25 MB</p></div><div class="section-heading">Your media</div><div class="photo-grid" id="upload-gallery">${uploadList.map(a=>`<button data-action="asset:${a.id}" title="${esc(a.name)}">${a.mime.startsWith('image/')?`<img src="${a.url||'/api/assets/'+a.id+(sync.token?'?share='+encodeURIComponent(sync.token):'')}" alt="${esc(a.name)}">`:icon(a.mime.startsWith('video/')?'video':'clock',30)}</button>`).join('')}</div>${!uploadList.length?'<p class="empty">Your uploaded files will appear here.</p>':''}`}
if(panel==='brand'){const b=doc.brand||{name:'My brand',colors:['#7654e8'],fonts:['Georgia','Arial']};html=panelHeading('Brand')+`<div class="brand-card"><div class="field"><label>Brand name</label><input id="brand-name" value="${esc(b.name)}"></div><div class="section-heading">Brand colors</div><div class="swatches">${b.colors.map((c,i)=>`<label class="swatch" style="background:${esc(c)};position:relative;overflow:hidden" title="${esc(c)}"><input data-brand-color="${i}" type="color" value="${c}" style="opacity:0;width:100%;height:100%;cursor:pointer"></label>`).join('')}${ib('brand-add-color','plus','Add brand color')}</div><div class="section-heading">Brand fonts</div><div style="font:28px Georgia;margin:15px 0">${esc(b.fonts[0])}</div><div style="font:17px Arial;margin-bottom:22px">${esc(b.fonts[1])} · Body text</div>${btn('brand-save','Save brand kit','check','primary-button full')}</div>${btn('brand-apply','Apply colors to this page','sparkle','outline-button full')}<div class="section-heading" style="margin-top:25px">Logo & imagery</div>${btn('upload','Upload brand assets','upload','outline-button full')}`}
if(panel==='draw'){html=panelHeading('Draw')+`<div class="text-presets">${btn('pen','Pen','draw','outline-button full '+(tool==='draw'?'active':''))}${btn('select-tool','Select elements','arrow','outline-button full')}</div><div class="field"><label>Ink color</label><input id="ink-color" type="color" value="${state.drawColor}" style="height:45px;width:100%"></div><div class="field"><label>Stroke width <span id="ink-width-label">${state.drawWidth}</span> px</label><input id="ink-width" type="range" min="1" max="40" value="${state.drawWidth}"></div><div class="swatches">${['#7654e8','#283f35','#e57853','#327dad','#111111'].map(c=>`<button class="swatch" data-action="ink:${c}" style="background:${c}" aria-label="Use ${c}"></button>`).join('')}</div><p class="empty">Draw directly on the page with your mouse, pen, or touch. Each stroke stays editable.</p>`}
if(panel==='layers'){html=panelHeading('Layers')+`<p style="font-size:12px;color:var(--muted)">Drag to reorder. Top layers appear in front.</p>`+pg().objects.slice().reverse().map(o=>`<div class="layer-item ${selected.includes(o.id)?'active':''}" data-layer="${o.id}" draggable="true"><div class="layer-icon">${icon(o.type==='text'?'text':o.type==='image'?'image':'elements',18)}</div><span class="layer-name">${esc(o.text?.split('\n')[0]||o.name||o.type)}</span>${ib('visibility:'+o.id,'eye',o.hidden?'Show':'Hide',o.hidden?'style="opacity:.3"':'')}${ib('lock:'+o.id,o.locked?'lock':'unlock',o.locked?'Unlock':'Lock')}</div>`).join('')+`<div style="margin-top:20px;display:flex;gap:8px">${btn('forward','Forward','layers','outline-button')}${btn('backward','Backward','','outline-button')}</div>`}
if(panel==='position'){const o=one();html=panelHeading('Position')+(o?`<div class="tabs">${btn('position','Arrange','','active')}${btn('layers','Layers')}</div><div class="shape-grid">${btn('align:left','Left')}${btn('align:center','Center')}${btn('align:right','Right')}${btn('align:top','Top')}${btn('align:middle','Middle')}${btn('align:bottom','Bottom')}</div><div class="field-row">${[['x','X',o.x],['y','Y',o.y],['w','Width',o.w],['h','Height',o.h],['rotation','Rotation',o.rotation||0],['opacity','Opacity %',Math.round((o.opacity??1)*100)]].map(([k,l,v])=>`<div class="field"><label>${l}</label><input type="number" data-prop="${k}" value="${Math.round(v)}"></div>`).join('')}</div><div class="field-row">${btn('forward','Forward','layers','outline-button')}${btn('backward','Backward','','outline-button')}</div><div class="field-row">${btn('group','Group','','outline-button')}${btn('ungroup','Ungroup','','outline-button')}</div>`:`<p class="empty">Select an element to adjust its position and size.</p>`)}
if(panel==='styles'){html=panelHeading('Styles')+`<div class="section-heading">Color palettes</div>`+[['#263f35','#f6f3e9','#e8b871','#9bae92'],['#342448','#eee5ff','#f3b6ca','#8c6fe8'],['#1e3268','#e8f1ff','#e66742','#72bfd4'],['#363132','#f1e8d9','#a96d48','#becd9b'],['#222a31','#dbff73','#4568de','#f58b56']].map((cs,i)=>`<button class="brand-card full" data-action="palette:${i}" style="padding:14px;gap:0">${cs.map(c=>`<span style="background:${c};height:43px;flex:1"></span>`).join('')}</button>`).join('')+`<div class="section-heading">Typography</div>${btn('font-pair:editorial','Editorial · Georgia / Arial','','text-preset full')}${btn('font-pair:modern','Modern · Manrope / DM Sans','','text-preset full','style="margin-top:12px"')}`}
if(panel==='comments'){html=panelHeading(LOCAL_MODE?'Personal notes':'Comments')+(LOCAL_MODE?'<p style="font-size:12px;color:var(--muted)">These notes stay on this device.</p>':'')+`<div id="comments-list"><p class="empty">Loading comments…</p></div><form id="comment-form"><div class="field"><textarea name="body" placeholder="Leave a comment on this page…" required maxlength="5000" rows="3" aria-label="Comment"></textarea></div><button type="submit" class="primary-button full">Post comment</button></form>`}
if(panel==='photo-edit'){const o=one();html=panelHeading('Edit image')+(o&&['image','video'].includes(o.type)?`<div class="tabs">${btn('photo-edit','Adjust','','active')}${btn('crop','Crop')}</div>${[['brightness','Brightness',100,0,200],['contrast','Contrast',100,0,200],['saturation','Saturation',100,0,200],['blur','Blur',0,0,15]].map(([k,l,d,min,max])=>`<div class="field"><label>${l} <span>${o[k]??d}</span></label><input data-prop="${k}" type="range" min="${min}" max="${max}" value="${o[k]??d}"></div>`).join('')}<div class="field"><label>Corner radius</label><input type="range" data-prop="radius" min="0" max="${Math.min(o.w,o.h)/2}" value="${o.radius||0}"></div>${btn('reset-image','Reset adjustments','','outline-button full')}`:'<p class="empty">Select an image first.</p>')}
host.innerHTML=html;if(panel==='design')renderTemplates();if(panel==='comments')loadComments()}
function renderTemplates(){const host=$('#template-grid');if(!host)return;const filtered=templates.filter(t=>(category==='All'||t.category===category)&&t.name.toLowerCase().includes(search.toLowerCase()));host.innerHTML=filtered.length?filtered.map(t=>`<button class="template-card" data-action="template:${t.id}" title="Apply ${esc(t.name)} template"><div class="template-art"><canvas data-template="${t.id}"></canvas></div><span class="template-caption">${esc(t.name)}</span></button>`).join(''):'<p class="empty">No templates found. Try another search.</p>';$$('[data-template]',host).forEach(c=>renderPage(c,templates.find(t=>t.id===c.dataset.template).create(),1200,675,.3))}
function setPanel(name){if(name==='projects'){home();return}if(view!=='editor'){view='editor';shell()}panel=name;state.mobilePanel=true;if(name!=='draw')tool='select';renderPanel();if(name==='uploads')loadUploads();if(innerWidth>700&&autoFit)fit()}
function add(o){transaction(()=>{pg().objects.push(o);selected=[o.id]});if(innerWidth<700){state.mobilePanel=false;renderPanel()}$('#interaction')?.focus()}
function duplicateObjects(){transaction(()=>{const copies=chosen().map(o=>({...clone(o),id:uid(),x:o.x+24,y:o.y+24,locked:false,group:null}));pg().objects.push(...copies);selected=copies.map(o=>o.id)})}
function removeObjects(){transaction(()=>{pg().objects=pg().objects.filter(o=>!selected.includes(o.id)||o.locked);selected=[]})}
function switchPage(i){finishText();pageIndex=clamp(i,0,doc.pages.length-1);selected=[];toolbar();draw();renderThumbs();if(['layers','comments'].includes(panel))renderPanel()}
function addPage(template){transaction(()=>{const p=template||page({background:pg().background,name:'Untitled page'});doc.pages.splice(pageIndex+1,0,p);pageIndex++;selected=[]});renderThumbs()}
function fieldChange(el){const prop=el.dataset.prop;if(!prop)return;let val=el.value;if(el.type==='number'||el.type==='range')val=+val;if(prop==='opacity')val=clamp(val/100,0,1);if(['w','h'].includes(prop))val=clamp(val,1,8192);if(prop==='fontSize')val=clamp(val,6,600);transaction(()=>{if(prop==='background')pg().background=val;else for(const o of chosen())if(!o.locked)o[prop]=val})}
function point(e){const r=$('#interaction').getBoundingClientRect();return{x:(e.clientX-r.left)/zoom,y:(e.clientY-r.top)/zoom}}
function bindCanvas(){const layer=$('#interaction');layer.addEventListener('pointerdown',e=>{if(e.button!==0||editing)return;closeContext();const p=point(e);if(!editable())return;const handle=e.target.closest('[data-handle]');const before=clone(doc);if(handle){const o=one();if(!o||o.locked)return;gesture={kind:handle.dataset.handle==='rotate'?'rotate':'resize',handle:handle.dataset.handle,start:p,before,initial:clone(o),pointer:e.pointerId}}else if(tool==='draw'){const o=object('path',{x:p.x,y:p.y,w:1,h:1,fill:state.drawColor,stroke:state.drawColor,strokeWidth:state.drawWidth,points:[[0,0]]});pg().objects.push(o);selected=[o.id];gesture={kind:'draw',start:p,before,id:o.id,pointer:e.pointerId}}else{const found=pg().objects.slice().reverse().find(o=>!o.hidden&&hit(o,p.x,p.y));if(found){let ids=found.group?pg().objects.filter(o=>o.group===found.group).map(o=>o.id):[found.id];if(e.shiftKey)selected=selected.includes(found.id)?selected.filter(id=>!ids.includes(id)):[...new Set([...selected,...ids])];else if(!selected.includes(found.id))selected=ids;if(!found.locked)gesture={kind:'move',start:p,before,initial:chosen().map(clone),pointer:e.pointerId};else gesture=null}else{if(!e.shiftKey)selected=[];gesture={kind:'marquee',start:p,before,pointer:e.pointerId,append:e.shiftKey,selected:[...selected]};const m=document.createElement('div');m.className='marquee';layer.append(m)}}if(gesture)layer.setPointerCapture(e.pointerId);e.preventDefault();toolbar();overlay()});
layer.addEventListener('pointermove',e=>{const p=point(e);sync.presence(pg().id,p.x,p.y);if(!gesture)return;const g=gesture,dx=p.x-g.start.x,dy=p.y-g.start.y;if(g.kind==='move'){for(const original of g.initial){const o=pg().objects.find(o=>o.id===original.id);if(!o||o.locked)continue;o.x=original.x+dx;o.y=original.y+dy;if(!e.altKey&&selected.length===1){const snap=6/zoom;for(const x of [0,doc.width/2-o.w/2,doc.width-o.w])if(Math.abs(o.x-x)<snap)o.x=x;for(const y of [0,doc.height/2-o.h/2,doc.height-o.h])if(Math.abs(o.y-y)<snap)o.y=y}}}
if(g.kind==='resize'){const o=one(),orig=g.initial,a=-(orig.rotation||0)*Math.PI/180,ldx=dx*Math.cos(a)-dy*Math.sin(a),ldy=dx*Math.sin(a)+dy*Math.cos(a);let w=orig.w,h=orig.h,lx=0,ly=0;if(g.handle.includes('e'))w=Math.max(5,orig.w+ldx);if(g.handle.includes('s'))h=Math.max(5,orig.h+ldy);if(g.handle.includes('w')){w=Math.max(5,orig.w-ldx);lx=(orig.w-w)/2}if(g.handle.includes('n')){h=Math.max(5,orig.h-ldy);ly=(orig.h-h)/2}if(e.shiftKey&&g.handle.length===2){h=w*orig.h/orig.w;ly=g.handle.includes('n')?(orig.h-h)/2:0}if(g.handle.includes('e'))lx=(w-orig.w)/2;if(g.handle.includes('s'))ly=(h-orig.h)/2;const r=(orig.rotation||0)*Math.PI/180,cx=orig.x+orig.w/2+lx*Math.cos(r)-ly*Math.sin(r),cy=orig.y+orig.h/2+lx*Math.sin(r)+ly*Math.cos(r);Object.assign(o,{x:cx-w/2,y:cy-h/2,w,h});if(o.type==='text'&&g.handle.length===2)o.fontSize=Math.max(6,orig.fontSize*w/orig.w);if(o.type==='path')o.points=orig.points.map(pt=>[pt[0]*w/orig.w,pt[1]*h/orig.h])}
if(g.kind==='rotate'){const o=one();let angle=Math.atan2(p.y-(o.y+o.h/2),p.x-(o.x+o.w/2))*180/Math.PI-90;if(e.shiftKey)angle=Math.round(angle/15)*15;o.rotation=angle}
if(g.kind==='draw'){const o=one();o.points.push([p.x-g.start.x,p.y-g.start.y]);const xs=o.points.map(p=>p[0]),ys=o.points.map(p=>p[1]);o.w=Math.max(1,Math.max(...xs));o.h=Math.max(1,Math.max(...ys))}
if(g.kind==='marquee'){const x=Math.min(p.x,g.start.x),y=Math.min(p.y,g.start.y),w=Math.abs(dx),h=Math.abs(dy);const m=$('.marquee');if(m)Object.assign(m.style,{left:x+'px',top:y+'px',width:w+'px',height:h+'px'});selected=[...new Set([...g.selected,...pg().objects.filter(o=>{const b=bounds(o);return !o.hidden&&b.x>=x&&b.y>=y&&b.right<=x+w&&b.bottom<=y+h}).map(o=>o.id)])]}draw()});
const up=e=>{if(!gesture)return;const g=gesture;gesture=null;$('.marquee')?.remove();if(layer.hasPointerCapture(e.pointerId))layer.releasePointerCapture(e.pointerId);if(g.kind==='draw'){const o=one(),pad=(o.strokeWidth||4)/2,minX=Math.min(...o.points.map(p=>p[0]))-pad,minY=Math.min(...o.points.map(p=>p[1]))-pad,maxX=Math.max(...o.points.map(p=>p[0]))+pad,maxY=Math.max(...o.points.map(p=>p[1]))+pad;o.x+=minX;o.y+=minY;o.w=Math.max(1,maxX-minX);o.h=Math.max(1,maxY-minY);o.points=o.points.map(p=>[p[0]-minX,p[1]-minY])}if(g.kind!=='marquee')commit(g.before);else{if(remoteDeferred){doc=remoteDeferred;remoteDeferred=null}draw();toolbar()}if(panel==='layers')renderPanel()};layer.addEventListener('pointerup',up);layer.addEventListener('pointercancel',e=>{if(gesture){doc=gesture.before;gesture=null;$('.marquee')?.remove();draw()}});
layer.addEventListener('dblclick',e=>{const p=point(e),o=pg().objects.slice().reverse().find(o=>!o.hidden&&!o.locked&&hit(o,p.x,p.y));if(o?.type==='text'){selected=[o.id];beginText(o)}else if(o?.type==='image'){selected=[o.id];action('crop')}});
layer.addEventListener('contextmenu',e=>{e.preventDefault();const p=point(e),o=pg().objects.slice().reverse().find(o=>!o.hidden&&hit(o,p.x,p.y));if(o&&!selected.includes(o.id)){selected=[o.id];overlay();toolbar()}context(e.clientX,e.clientY)});
$('#canvas-area').addEventListener('wheel',e=>{if(e.ctrlKey||e.metaKey){e.preventDefault();autoFit=false;zoom=clamp(zoom*(e.deltaY>0?.93:1.07),.1,3);layoutCanvas()}},{passive:false});
$('#canvas-area').addEventListener('dragover',e=>e.preventDefault());$('#canvas-area').addEventListener('drop',e=>{if(e.dataTransfer.files.length){e.preventDefault();uploadFiles(e.dataTransfer.files)}})}
function beginText(o){if(!editable()||editing)return;const before=clone(doc);const input=document.createElement('textarea');input.className='text-edit';input.value=o.text;input.setAttribute('aria-label','Edit text');Object.assign(input.style,{left:o.x+'px',top:o.y+'px',width:o.w+'px',height:Math.max(o.h,o.fontSize*1.5)+'px',font:font(o),lineHeight:String(o.lineHeight||1.2),color:o.fill,textAlign:o.align||'left',letterSpacing:(o.letterSpacing||0)+'px',transform:`rotate(${o.rotation||0}deg)`});editing={input,id:o.id,before};$('#artboard').append(input);const originalOpacity=o.opacity??1;o.opacity=0;window.renderer.render(pg(),doc.width,doc.height,zoom);o.opacity=originalOpacity;input.focus();input.select();input.addEventListener('blur',finishText);input.addEventListener('keydown',e=>{if(e.key==='Escape'){input.value=before.pages[pageIndex].objects.find(x=>x.id===o.id).text;finishText()}if(e.key==='Enter'&&(e.ctrlKey||e.metaKey)){e.preventDefault();finishText()}})}
function finishText(){if(!editing)return;const {input,id,before}=editing;const o=pg().objects.find(o=>o.id===id);if(o)o.text=input.value;editing=null;input.remove();commit(before)}
function closeContext(){$('.context-menu')?.remove()}
function context(x,y){closeContext();const m=document.createElement('div');m.className='context-menu';m.style.left=Math.min(x,innerWidth-220)+'px';m.style.top=Math.min(y,innerHeight-340)+'px';m.innerHTML=[['copy','Copy','copy','Ctrl+C'],['paste','Paste','','Ctrl+V'],['duplicate','Duplicate','copy','Ctrl+D'],['delete','Delete','trash','Del'],['group','Group','','Ctrl+G'],['ungroup','Ungroup','',''],['forward','Bring forward','layers',']'],['backward','Send backward','','['],['lock','Lock / unlock','lock',''],['layers','Show layers','layers','']].map(([a,l,i,k])=>`<button data-action="${a}">${i?icon(i,16):''}${l}<kbd>${k}</kbd></button>`).join('');document.body.append(m)}
function modal(title,body,wide=false){const m=$('#modal');m.style.width=wide?'650px':'470px';m.innerHTML=`<div class="modal-head"><h2>${title}</h2>${ib('close-modal','close','Close dialog')}</div><div class="modal-body">${body}</div>`;if(!m.open)m.showModal()}
function closeModal(){$('#modal').close()}
async function share(){if(LOCAL_MODE){modal('Share a design',`<p>This edition saves designs on this device. Download a portable design file to send an editable copy, including uploaded media.</p>${btn('portable-export','Download editable design','download','primary-button full')}<div class="modal-separator"></div><p>Live collaboration, accounts, and link permissions are available in the hosted workspace, subject to its access settings.</p><a class="outline-button full" href="${HOSTED_APP}" target="_blank" rel="noopener" style="display:flex;justify-content:center;text-decoration:none">Open hosted workspace</a>`);return}if(!sync.id){toast('Save your design before sharing.');return}await sync.settled();let sharing={members:[]};if(sync.role==='owner')sharing=await sync.request(`projects/${sync.id}/sharing`);modal('Share this design',`<p>Give people access to your design and work together.</p><form id="share-form"><div class="copy-row"><input name="email" type="email" placeholder="Enter an email address" aria-label="Collaborator email" required><select name="role" aria-label="Collaborator permission"><option value="edit">Can edit</option><option value="comment">Can comment</option><option value="view">Can view</option></select></div><button class="primary-button full" style="margin-top:12px" ${sync.role!=='owner'?'disabled':''}>Add collaborator</button></form><div class="modal-separator"></div><strong style="font-size:13px">People with access</strong><div class="share-person"><div class="avatar">${esc(user?.name?.[0]||'Y')}</div><div class="details">${esc(user?.name||'You')}<small>${esc(user?.email||'')}</small></div><span class="permission-tag">${sync.role==='owner'?'Owner':sync.role}</span></div>${sharing.members.map(m=>`<div class="share-person"><div class="avatar">${esc(m.email[0].toUpperCase())}</div><div class="details">${esc(m.email)}</div><span class="permission-tag">Can ${m.role}</span>${ib('remove-member:'+m.email,'close','Remove access')}</div>`).join('')}<div class="modal-separator"></div><div class="field"><label>Link access</label><select id="link-role"><option value="view">Anyone with the link can view</option><option value="comment">Anyone with the link can comment</option><option value="edit">Anyone with the link can edit</option></select></div>${btn('copy-link','Create & copy link','link','primary-button full',sync.role!=='owner'?'disabled':'')}<div id="share-link-output"></div><p style="font-size:12px">Collaborators must be signed in and permitted to open this site. Adding access does not send an email.</p>${sync.role==='owner'?btn('revoke-links','Revoke all links','','outline-button full'):''}<div class="modal-separator"></div>${btn('export','Download design','download','outline-button full')}`)}
async function exportDialog(){modal('Download your design',`<div class="export-preview"><canvas id="export-preview"></canvas></div><form id="export-form"><div class="field"><label>File type</label><select name="format" id="export-format"><option value="png">PNG — high quality image</option><option value="jpeg">JPG — smaller image</option><option value="pdf">PDF — all pages</option><option value="svg">SVG — editable text & shapes</option><option value="json">Velora design — editable project</option><option value="webm">WebM — timed presentation video</option></select></div><div class="field-row"><div class="field"><label>Page</label><select name="page">${doc.pages.map((p,i)=>`<option value="${i}" ${i===pageIndex?'selected':''}>Page ${i+1}</option>`).join('')}</select></div><div class="field"><label>Image scale</label><select name="scale"><option value="1">1× · ${doc.width} × ${doc.height}</option><option value="2">2× · ${doc.width*2} × ${doc.height*2}</option></select></div></div><p class="export-note">PDF includes every page as a high-resolution image. SVG retains text and basic shapes; effects and media are embedded images.</p><button class="primary-button full" id="download-button">${icon('download')}Download</button></form>`);await renderPage($('#export-preview'),pg(),doc.width,doc.height,.3)}
async function exportFile(format,index=pageIndex,scale=1){const name=doc.name.replace(/[^\p{L}\p{N}_-]/gu,'-')||'velora-design';if(format==='json'){download(JSON.stringify(LOCAL_MODE?await sync.local.portable(doc):doc,null,2),name+'.velora.json','application/json');return}await document.fonts.ready;if(format==='pdf'){download(await exportPDF(doc),name+'.pdf');return}if(format==='svg'){download(await pageSVG(doc.pages[index],doc.width,doc.height),name+'.svg','image/svg+xml');return}if(format==='webm'){await exportVideo(name);return}if(doc.width*doc.height*scale*scale>40e6)throw Error('Choose a smaller image scale for this design.');const c=document.createElement('canvas');await renderPage(c,doc.pages[index],doc.width,doc.height,scale);const blob=await new Promise(r=>c.toBlob(r,'image/'+format,.95));download(blob,name+'.'+(format==='jpeg'?'jpg':'png'))}
async function exportVideo(name){if(!window.MediaRecorder||!HTMLCanvasElement.prototype.captureStream)throw Error('Video export is not available in this browser.');const type=['video/webm;codecs=vp9','video/webm;codecs=vp8','video/webm'].find(t=>MediaRecorder.isTypeSupported(t));if(!type)throw Error('This browser cannot encode WebM video.');const canvas=document.createElement('canvas');await renderPage(canvas,doc.pages[0],doc.width,doc.height,Math.min(1,1920/doc.width));const stream=canvas.captureStream(30),rec=new MediaRecorder(stream,{mimeType:type}),parts=[];rec.ondataavailable=e=>{if(e.data.size)parts.push(e.data)};const done=new Promise(r=>rec.onstop=r);rec.start();for(let i=0;i<doc.pages.length;i++){await renderPage(canvas,doc.pages[i],doc.width,doc.height,Math.min(1,1920/doc.width));status(`Recording page ${i+1} of ${doc.pages.length}…`);await new Promise(r=>setTimeout(r,(doc.pages[i].duration||5)*1000))}rec.stop();await done;stream.getTracks().forEach(t=>t.stop());download(new Blob(parts,{type:'video/webm'}),name+'.webm');status('All changes saved')}
async function loadUploads(){if(!sync.id)return;try{uploadList=await sync.request(`projects/${sync.id}/assets`);if(panel==='uploads')renderPanel()}catch(e){toast(e.message)}}
async function uploadFiles(files){if(!editable())return;if(!sync.id){toast('Sign in and save a design before uploading media.');return}for(const f of files){try{status('Uploading '+f.name+'…');const form=new FormData();form.append('file',f);const a=await sync.request(`projects/${sync.id}/assets`,{method:'POST',body:form});uploadList.unshift(a);await insertAsset(a);toast(f.name+' uploaded')}catch(e){toast(e.message)}}status('All changes saved');if(panel==='uploads')renderPanel()}
async function insertAsset(a){if(a.mime.startsWith('audio/')){a.url=await mediaURL('/api/assets/'+a.id);modal('Audio track',`<p>${esc(a.name)}</p><audio controls src="${a.url||'/api/assets/'+a.id+(sync.token?'?share='+encodeURIComponent(sync.token):'')}" style="width:100%"></audio><p>Audio can be previewed here. Timeline mixing and audio in video exports are not available in this version.</p>`);return}const type=a.mime.startsWith('video/')?'video':'image',src='/api/assets/'+a.id;const m=await loadMedia(src,type);const w=m.naturalWidth||m.videoWidth,h=m.naturalHeight||m.videoHeight;const width=Math.min(doc.width*.65,w),height=width*h/w;add(object(type,{src,name:a.name,x:(doc.width-width)/2,y:(doc.height-height)/2,w:width,h:height}));if(type==='video')toast('Video added. Use Present to play it.')}
async function loadComments(){if(!sync.id){$('#comments-list').innerHTML='<p class="empty">Save your design to start a conversation.</p>';return}try{const list=await sync.request(`projects/${sync.id}/comments`);if(panel!=='comments')return;$('#comments-list').innerHTML=list.filter(c=>c.page===pg().id).map(c=>`<div class="comment-card ${c.resolved?'resolved':''}"><div class="comment-author"><span class="avatar">${esc(c.name[0].toUpperCase())}</span>${esc(c.name)}</div><p>${esc(c.body)}</p><small>${new Date(c.created).toLocaleDateString()}</small><button data-action="resolve:${c.id}:${c.resolved?0:1}" style="float:right">${c.resolved?'Reopen':'Resolve'}</button></div>`).join('')||`<p class="empty">${icon('comment',30)}Start a conversation.<br>Share a thought on this page.</p>`}catch(e){$('#comments-list').innerHTML=`<p class="empty">${esc(e.message)}</p>`}}
async function home(){finishText();if(sync.pending.length){try{await sync.settled()}catch(e){toast(e.message);return}}view='home';$('#panel').style.display='none';$('#editor').style.display='none';$('.home-screen')?.remove();const main=document.createElement('main');main.className='home-screen';main.innerHTML=`<div class="home-header"><div><h1>Your next great idea starts here.</h1><p>A space for everything you want to create.</p></div>${btn('new-design','Create a design','plus','primary-button')}</div><div class="home-banner"><h2>What will you create today?</h2><div class="format-list">${[['presentation','Presentations','play'],['social','Social media','image'],['poster','Posters','note'],['document','Documents','text'],['video','Videos','video'],['whiteboard','Whiteboards','elements'],['custom','Custom size','plus']].map(([a,l,i])=>`<button class="format-button" data-action="format:${a}"><span>${icon(i,25)}</span>${l}</button>`).join('')}</div></div><div class="section-heading" style="font-size:20px">Recent designs</div><div class="home-search-row"><div class="search">${icon('search',18)}<input id="project-search" placeholder="Search your designs" aria-label="Search designs"></div><select id="project-filter" aria-label="Filter projects"><option value="all">All designs</option><option value="starred">Starred</option><option value="shared">Shared with you</option></select><select id="folder-filter" aria-label="Filter folders"><option value="">All folders</option></select>${btn('import','Import design','upload','outline-button')}</div><div id="project-grid" class="project-grid"><p class="empty">Loading your designs…</p></div><div class="section-heading" style="font-size:20px;margin-top:40px">A little inspiration</div><div class="home-templates">${templates.map(t=>`<button class="template-card" data-action="new-template:${t.id}"><div class="template-art"><canvas data-home-template="${t.id}"></canvas></div><span class="template-caption">${esc(t.name)}</span></button>`).join('')}</div>`;$('.workspace').append(main);$$('[data-home-template]').forEach(c=>renderPage(c,templates.find(t=>t.id===c.dataset.homeTemplate).create(),1200,675,.5));try{projects=await sync.request('projects');renderProjects();const folders=[...new Set(projects.map(p=>p.folder).filter(Boolean))];$('#folder-filter').innerHTML='<option value="">All folders</option>'+folders.map(f=>`<option>${esc(f)}</option>`).join('')}catch(e){$('#project-grid').innerHTML=`<p class="empty">${esc(e.message)}</p>`}}
function renderProjects(){const q=($('#project-search')?.value||'').toLowerCase(),filter=$('#project-filter')?.value,folder=$('#folder-filter')?.value;const list=projects.filter(p=>p.name.toLowerCase().includes(q)&&(filter!=='starred'||p.starred)&&(filter!=='shared'||p.owner!==user?.id)&&(!folder||p.folder===folder));$('#project-grid').innerHTML=list.map(p=>`<article class="project-card" data-project="${p.id}" tabindex="0" role="button" aria-label="Open ${esc(p.name)}"><div class="project-cover"><canvas data-project-preview="${p.id}"></canvas></div><div class="project-info"><div><strong>${esc(p.name)}</strong><small>${p.pageCount} pages · ${new Date(p.updated).toLocaleDateString()}${p.folder?' · '+esc(p.folder):''}</small></div>${ib('project-menu:'+p.id,'more','Design actions')}</div></article>`).join('')||'<p class="empty">No designs here yet. Create something you love.</p>';$$('[data-project-preview]').forEach(c=>{const p=projects.find(p=>p.id===c.dataset.projectPreview);renderPage(c,p.preview,p.width,p.height,400/p.width)})}
async function openProject(id){try{await sync.settled();const r=await sync.open(id);if(!r)return;doc=clone(sync.server);for(const op of sync.pending)apply(doc,op.changes);pageIndex=0;selected=[];history=new History();view='editor';panel='design';search='';category='All';autoFit=true;shell();status('All changes saved');setAddress(id)}catch(e){toast(e.message)}}
function setAddress(id){if(LOCAL_MODE)localStorage.setItem('velora-last-project',id);const q=new URLSearchParams({project:id});if(sync.token)q.set('share',sync.token);window.history.replaceState(null,'','?'+q);try{parent.history.replaceState(null,'',new URL(APP_ROOT).pathname+'?'+q)}catch{}}
async function createProject(data){try{await sync.settled();sync.token='';doc=await sync.create(data);pageIndex=0;selected=[];history=new History();view='editor';autoFit=true;shell();status('All changes saved');setAddress(doc.id)}catch(e){toast(e.message)}}
function newDesignDialog(format='presentation'){const sizes={presentation:[1200,675],social:[1080,1080],poster:[840,1188],document:[794,1123],video:[1920,1080],whiteboard:[2400,1600],custom:[1200,675]},[w,h]=sizes[format]||sizes.presentation;modal('Create a design',`<form id="new-design-form"><div class="field"><label>Design name</label><input name="name" value="Untitled ${format==='custom'?'design':format}" required maxlength="150"></div><div class="field-row"><div class="field"><label>Width (px)</label><input name="width" type="number" value="${w}" min="32" max="8192" required></div><div class="field"><label>Height (px)</label><input name="height" type="number" value="${h}" min="32" max="8192" required></div></div><div class="modal-actions"><button class="primary-button">Create design</button></div></form>`)}
async function present(){finishText();if(presenting)return;presenting=true;let i=pageIndex,playing=false,timer,frame,epoch=0;const host=document.createElement('div');host.className='present-overlay';host.innerHTML=`<canvas></canvas><div class="present-controls">${btn('present-prev','','chevron','','style="transform:rotate(180deg)" aria-label="Previous slide"')}${btn('present-auto','Play','play')}<span id="present-page"></span>${btn('present-next','','chevron','','aria-label="Next slide"')}${btn('present-exit','','close','','aria-label="Exit presentation"')}</div>`;document.body.append(host);const canvas=$('canvas',host);const mediaEls=[];const render=async()=>{const current=++epoch;cancelAnimationFrame(frame);for(const el of mediaEls)el.pause();mediaEls.length=0;for(const o of doc.pages[i].objects.filter(o=>o.type==='video')){try{const v=await loadMedia(o.src,'video');v.currentTime=o.trimStart||0;await v.play();mediaEls.push(v)}catch{}}if(current!==epoch)return;const paint=async()=>{if(!presenting||current!==epoch)return;await renderPage(canvas,doc.pages[i],doc.width,doc.height,Math.min(1.5,1920/doc.width));if(mediaEls.length)frame=requestAnimationFrame(paint)};await paint();$('#present-page',host).textContent=`${i+1} / ${doc.pages.length}`;if(playing){clearTimeout(timer);timer=setTimeout(()=>{if(i<doc.pages.length-1){i++;render()}else{playing=false;$('#present-page',host).textContent+=' · Finished'}},(doc.pages[i].duration||5)*1000)}};const end=()=>{presenting=false;epoch++;clearTimeout(timer);cancelAnimationFrame(frame);mediaEls.forEach(v=>v.pause());host.remove();document.removeEventListener('keydown',key)};const key=e=>{if(e.key==='Escape')end();if(e.key==='ArrowRight'||e.key===' '){e.preventDefault();i=Math.min(i+1,doc.pages.length-1);render()}if(e.key==='ArrowLeft'){i=Math.max(0,i-1);render()}};document.addEventListener('keydown',key);host.addEventListener('click',e=>{const a=e.target.closest('[data-action]')?.dataset.action;if(a==='present-exit')end();if(a==='present-next'){i=Math.min(i+1,doc.pages.length-1);render()}if(a==='present-prev'){i=Math.max(0,i-1);render()}if(a==='present-auto'){playing=!playing;clearTimeout(timer);e.target.closest('button').innerHTML=icon('play')+(playing?'Pause':'Play');if(playing)render()}});await render()}
const palettes=[['#263f35','#f6f3e9','#e8b871','#9bae92'],['#342448','#eee5ff','#f3b6ca','#8c6fe8'],['#1e3268','#e8f1ff','#e66742','#72bfd4'],['#363132','#f1e8d9','#a96d48','#becd9b'],['#222a31','#dbff73','#4568de','#f58b56']];
async function action(a,event){const [kind,arg,...rest]=a.split(':');closeContext();if(kind==='panel'){setPanel(arg);return}if(kind==='category'){category=arg;renderPanel();return}if(kind==='page'){switchPage(+arg);return}if(kind==='template'){const t=templates.find(t=>t.id===arg);modal('Use this template?',`<p>This will replace the contents of the current page. You can undo this change.</p><div class="modal-actions">${btn('close-modal','Cancel','','outline-button')}${btn('apply-template:'+arg,'Use template','','primary-button')}</div>`);return}if(kind==='apply-template'){const t=templates.find(t=>t.id===arg);transaction(()=>{const id=pg().id,p=t.create(),sx=doc.width/1200,sy=doc.height/675;p.id=id;for(const o of p.objects){o.x*=sx;o.y*=sy;o.w*=sx;o.h*=sy;if(o.fontSize)o.fontSize*=Math.min(sx,sy)}doc.pages[pageIndex]=p;selected=[]});closeModal();if(innerWidth<700){state.mobilePanel=false;renderPanel()}return}
if(kind==='new-template'){const t=templates.find(t=>t.id===arg);await createProject(project({name:t.name,pages:[t.create()]}));return}if(kind==='format'){newDesignDialog(arg);return}if(kind==='photo'){const o=object('image',{src:assets[+arg].src,w:500,h:330,x:(doc.width-500)/2,y:(doc.height-330)/2});add(o);return}if(kind==='frame'){add(object('image',{src:assets[1].src,w:320,h:320,x:(doc.width-320)/2,y:(doc.height-320)/2,radius:arg==='round'?35:arg==='circle'?160:0}));return}if(kind==='shape'){add(object(arg==='arrow'?'line':arg,{x:doc.width/2-140,y:doc.height/2-100,w:280,h:arg==='line'||arg==='arrow'?20:200,fill:'#9572de',arrow:arg==='arrow',values:arg==='chart'?[45,80,62,96]:undefined}));return}
if(kind==='text'){if(arg==='pair'||arg==='bold-pair'){transaction(()=>{const group=uid(),x=doc.width/2-240,y=doc.height/2-70;const a=object('text',{text:arg==='pair'?'The good things.':'MAKE IT',x,y,w:480,h:90,fontSize:60,fontFamily:arg==='pair'?'Georgia':'Arial',italic:arg==='pair',bold:arg!=='pair',fill:'#283f35',group}),b=object('text',{text:arg==='pair'?'ARE THE SIMPLE THINGS':'happen.',x,y:y+90,w:480,h:60,fontSize:arg==='pair'?18:46,fontFamily:arg==='pair'?'Arial':'Georgia',fill:'#283f35',letterSpacing:arg==='pair'?3:0,group});pg().objects.push(a,b);selected=[a.id,b.id]})}else{const size=arg==='heading'?64:arg==='subheading'?38:24;add(object('text',{text:arg==='heading'?'Add a heading':arg==='subheading'?'Add a subheading':'Your story starts here.',x:doc.width/2-250,y:doc.height/2-size,w:500,h:size*1.8,fontSize:size,fontFamily:'Arial',bold:arg==='heading',fill:'#283f35'}))}return}
if(kind==='asset'){await insertAsset(uploadList.find(x=>x.id===arg));return}if(kind==='visibility'||(kind==='lock'&&arg)){transaction(()=>{const o=pg().objects.find(o=>o.id===arg);if(o)o[kind==='visibility'?'hidden':'locked']=!o[kind==='visibility'?'hidden':'locked']});renderPanel();return}if(kind==='align'){transaction(()=>{for(const o of chosen()){if(o.locked)continue;if(arg==='left')o.x=0;if(arg==='center')o.x=(doc.width-o.w)/2;if(arg==='right')o.x=doc.width-o.w;if(arg==='top')o.y=0;if(arg==='middle')o.y=(doc.height-o.h)/2;if(arg==='bottom')o.y=doc.height-o.h}});return}if(kind==='palette'){const cs=palettes[+arg];transaction(()=>{pg().background=cs[1];let n=0;for(const o of pg().objects)if(!['image','video'].includes(o.type))o.fill=o.type==='text'?cs[0]:cs[2+(n++%2)]});return}if(kind==='ink'){state.drawColor=arg;renderPanel();return}if(kind==='font-pair'){transaction(()=>{for(const o of pg().objects)if(o.type==='text')o.fontFamily=arg==='editorial'?(o.fontSize>30?'Georgia':'Arial'):(o.fontSize>30?'Manrope':'DM Sans')});return}
if(kind==='resolve'){await sync.request(`projects/${sync.id}/comments`,{method:'PATCH',body:JSON.stringify({id:arg,resolved:+rest[0]})});loadComments();return}if(kind==='remove-member'){await sync.request(`projects/${sync.id}/sharing`,{method:'DELETE',body:JSON.stringify({email:arg})});share();return}if(kind==='restore-version'){const data=await sync.request(`projects/${sync.id}/snapshots/${arg}`);transaction(()=>{doc=data;selected=[];pageIndex=0});closeModal();toast('Version restored. You can undo this change.');return}
if(kind==='project-menu'){const p=projects.find(p=>p.id===arg);modal('Design settings',`<form id="project-settings-form" data-id="${p.id}"><div class="field"><label>Folder</label><input name="folder" value="${esc(p.folder)}" placeholder="e.g. Summer campaign" maxlength="80"></div><label style="display:flex;gap:9px;align-items:center"><input type="checkbox" name="starred" ${p.starred?'checked':''}>Star this design</label><div class="modal-actions"><button class="primary-button">Save settings</button></div></form><div class="modal-separator"></div>${btn('duplicate-project:'+p.id,'Duplicate design','copy','outline-button full')}${btn('delete-project:'+p.id,'Move to trash','trash','outline-button full','style="margin-top:10px;color:#b34660"')}`);return}if(kind==='duplicate-project'){const r=await sync.request('projects/'+arg);const d=clone(r.data);d.name+=' (copy)';await createProject(d);closeModal();return}if(kind==='delete-project'){modal('Move design to trash?',`<p>This removes the design from your workspace.</p><div class="modal-actions">${btn('close-modal','Cancel','','outline-button')}${btn('confirm-delete-project:'+arg,'Move to trash','trash','primary-button')}</div>`);return}if(kind==='confirm-delete-project'){await sync.request('projects/'+arg,{method:'DELETE'});closeModal();home();return}
switch(a){case'home':case'explore':await home();break;case'close-panel':state.mobilePanel=false;$('#panel').classList.remove('mobile-open');break;case'close-modal':closeModal();break;case'file':modal('Your design',`<div class="text-presets">${btn('new-design','Create a new design','plus','outline-button full')}${btn('home','Open designs','folder','outline-button full')}${btn('save-version','Save a version','clock','outline-button full')}${btn('versions','Version history','clock','outline-button full')}${btn('import','Import editable design','upload','outline-button full')}${btn('export','Download','download','outline-button full')}${btn('theme','Switch light / dark theme','moon','outline-button full')}</div>`);break;
case'new-design':newDesignDialog();break;case'add-text':action('text:heading');break;case'undo':case'redo':if(editable()){const before=clone(doc);if(history[a](doc)){sync.queue(before,doc);selected=[];pageIndex=Math.min(pageIndex,doc.pages.length-1);draw();toolbar();renderThumbs();if(panel==='layers')renderPanel()}}break;case'delete':removeObjects();break;case'duplicate':duplicateObjects();break;case'copy':clipboard=clone(chosen());toast('Elements copied');break;case'paste':if(clipboard.length)transaction(()=>{const copies=clipboard.map(o=>({...clone(o),id:uid(),x:o.x+24,y:o.y+24,group:null,locked:false}));pg().objects.push(...copies);selected=copies.map(o=>o.id)});break;case'bold':case'italic':transaction(()=>{for(const o of chosen())if(o.type==='text')o[a]=!o[a]});break;case'text-align':transaction(()=>{for(const o of chosen())o.align=({left:'center',center:'right',right:'left'})[o.align||'left']});break;case'lock':transaction(()=>{for(const o of chosen())o.locked=!o.locked});break;case'group':if(selected.length>1)transaction(()=>{const group=uid();for(const o of chosen())o.group=group});else toast('Select at least two elements to group.');break;case'ungroup':transaction(()=>{for(const o of chosen())o.group=null});break;case'forward':case'backward':transaction(()=>{const ids=[...selected];if(a==='forward')ids.reverse();for(const id of ids){const i=pg().objects.findIndex(o=>o.id===id),j=clamp(i+(a==='forward'?1:-1),0,pg().objects.length-1);if(i>=0)[pg().objects[i],pg().objects[j]]=[pg().objects[j],pg().objects[i]]}});break;
case'add-page':addPage();break;case'duplicate-page':{const p=clone(pg());p.id=uid();p.name+=' (copy)';const groups=new Map();for(const o of p.objects){o.id=uid();if(o.group){if(!groups.has(o.group))groups.set(o.group,uid());o.group=groups.get(o.group)}}addPage(p);break}case'delete-page':if(doc.pages.length===1){toast('Keep at least one page in your design.');break}transaction(()=>{doc.pages.splice(pageIndex,1);pageIndex=Math.min(pageIndex,doc.pages.length-1);selected=[]});break;case'page-up':switchPage(pageIndex-1);break;case'page-down':switchPage(pageIndex+1);break;case'fit':autoFit=true;fit();break;case'layers':case'position':case'styles':case'comments':case'photo-edit':setPanel(a);break;case'templates-tab':panel='design';renderPanel();break;case'upload':$('#file-input').click();break;case'pen':tool='draw';renderPanel();break;case'select-tool':tool='select';renderPanel();break;case'more':{const r=event?.target.closest('button').getBoundingClientRect();context(r?.left||innerWidth-250,r?.bottom||120);break}case'opacity':setPanel('position');break;
case'resize':modal('Resize your design',`<form id="resize-form"><p>Change the page size and scale your design to fit.</p><div class="field-row"><div class="field"><label>Width (px)</label><input name="width" type="number" min="32" max="8192" value="${doc.width}" required></div><div class="field"><label>Height (px)</label><input name="height" type="number" min="32" max="8192" value="${doc.height}" required></div></div><label><input type="checkbox" name="scale" checked> Scale elements with the page</label><div class="modal-actions"><button class="primary-button">Resize design</button></div></form>`);break;
case'crop':{const o=one();if(!o||!['image','video'].includes(o.type)){toast('Select an image to crop.');break}modal('Crop image',`<form id="crop-form"><div class="field"><label>Zoom</label><input name="cropZoom" type="range" min="1" max="4" step="0.05" value="${o.cropZoom||1}"></div><div class="field-row"><div class="field"><label>Horizontal offset</label><input name="cropX" type="number" value="${o.cropX||0}"></div><div class="field"><label>Vertical offset</label><input name="cropY" type="number" value="${o.cropY||0}"></div></div><div class="field"><label>Fit mode</label><select name="fit"><option value="cover" ${o.fit!=='contain'?'selected':''}>Fill frame</option><option value="contain" ${o.fit==='contain'?'selected':''}>Fit whole image</option></select></div><div class="modal-actions"><button class="primary-button">Apply crop</button></div></form>`);break}case'flip':transaction(()=>{for(const o of chosen())o.flipX=!o.flipX});break;case'reset-image':transaction(()=>{for(const o of chosen())Object.assign(o,{brightness:100,contrast:100,saturation:100,blur:0,cropZoom:1,cropX:0,cropY:0,radius:0,flipX:false,flipY:false})});renderPanel();break;
case'chart-edit':{const o=one();modal('Edit chart data',`<form id="chart-form"><div class="field"><label>Labels, separated by commas</label><input name="labels" value="${esc((o.labels||['Q1','Q2','Q3','Q4']).join(', '))}" required></div><div class="field"><label>Values, separated by commas</label><input name="values" value="${esc((o.values||[45,80,62,96]).join(', '))}" required></div><button class="primary-button full">Update chart</button></form>`);break}
case'brand-add-color':transaction(()=>{doc.brand.colors.push('#a58bda')});break;case'brand-save':transaction(()=>{doc.brand.name=$('#brand-name').value;doc.brand.colors=$$('[data-brand-color]').map(i=>i.value)});toast('Brand kit saved');break;case'brand-apply':transaction(()=>{pg().background=doc.brand.colors[1]||'#fff';for(const o of pg().objects)if(o.type==='text')o.fill=doc.brand.colors[0]});toast('Brand colors applied');break;
case'timing':modal('Page timing',`<form id="timing-form"><p>Set how long each page appears during autoplay and video export.</p>${doc.pages.map((p,i)=>`<div class="field-row"><div class="field"><label>Page ${i+1} · ${esc(p.name)}</label></div><div class="field"><input name="duration-${i}" type="number" min="1" max="120" step="0.5" value="${p.duration||5}" aria-label="Page ${i+1} duration"></div></div>`).join('')}<button class="primary-button full">Save timing</button></form>`);break;
case'notes':notesOpen=!notesOpen;$('.note-panel')?.remove();if(notesOpen){const n=document.createElement('div');n.className='note-panel';n.innerHTML=`<label style="display:block;margin-bottom:8px;font-size:12px;font-weight:600">Page notes</label><textarea id="page-notes" placeholder="Add speaker notes for this page…">${esc(pg().notes||'')}</textarea>`;$('#canvas-area').append(n)}break;
case'grid':modal('All pages',`<div class="home-templates">${doc.pages.map((p,i)=>`<button class="template-card" data-action="overview-page:${i}"><div class="template-art"><canvas data-overview="${i}"></canvas></div><span class="template-caption">${i+1}. ${esc(p.name)}</span></button>`).join('')}</div>`,true);$$('[data-overview]').forEach(c=>renderPage(c,doc.pages[+c.dataset.overview],doc.width,doc.height,.3));break;case'fullscreen':if(document.fullscreenElement)document.exitFullscreen();else document.documentElement.requestFullscreen?.().catch(()=>toast('Fullscreen is unavailable in this browser.'));break;
case'portable-export':await exportFile('json');closeModal();toast('Portable design downloaded');break;case'export':await exportDialog();break;case'share':await share();break;case'copy-link':{const r=await sync.request(`projects/${sync.id}/sharing`,{method:'POST',body:JSON.stringify({role:$('#link-role').value})});const url=location.origin+'/?project='+sync.id+'&share='+encodeURIComponent(r.token);$('#share-link-output').innerHTML=`<div class="copy-row"><input readonly value="${esc(url)}" aria-label="Share link"></div>`;try{await navigator.clipboard.writeText(url);toast('Share link copied')}catch{$('#share-link-output input').select();toast('Select and copy your share link')}break}case'revoke-links':await sync.request(`projects/${sync.id}/sharing`,{method:'DELETE',body:'{}'});toast('All share links revoked');share();break;case'present':await present();break;
case'save-version':if(!sync.id){toast('Save the design first.');break}modal('Save a version',`<form id="version-form"><div class="field"><label>Version name</label><input name="name" value="${esc(new Date().toLocaleDateString()+' · '+doc.name)}" maxlength="100" required></div><button class="primary-button full">Save version</button></form>`);break;case'versions':{if(!sync.id)break;const list=await sync.request(`projects/${sync.id}/snapshots`);modal('Version history',list.length?list.map(v=>`<div class="share-person"><div class="details">${esc(v.name)}<small>${new Date(v.created).toLocaleString()}</small></div>${btn('restore-version:'+v.id,'Restore','','outline-button')}</div>`).join(''):'<p>No saved versions yet. Use File → Save a version to create a checkpoint.</p>');break}
case'import':{const input=document.createElement('input');input.type='file';input.accept='.json,.velora';input.onchange=async()=>{try{const f=input.files[0];if(!f)return;if(f.size>(LOCAL_MODE?90e6:2e6))throw Error('Design file is too large.');const input=JSON.parse(await f.text());if(LOCAL_MODE&&input.format==='velora-portable'){await sync.settled();const id=await sync.local.importPortable(input);await openProject(id)}else{const d=validateProject(input);await createProject(d)}closeModal()}catch(e){toast(e.message)}};input.click();break}case'theme':localStorage.setItem('velora-theme',document.body.classList.contains('theme-dark')?'light':'dark');document.body.classList.toggle('theme-dark');break;
case'diagnostics':modal('Rendering & document',`<p>Your current rendering backend is <strong>${esc(backend)}</strong>.</p><table class="keyboard-table"><tr><td>Page size</td><td>${doc.width} × ${doc.height} px</td></tr><tr><td>Elements on page</td><td>${pg().objects.length}</td></tr><tr><td>Last render</td><td>${window.renderer.metrics.ms.toFixed(2)} ms</td></tr><tr><td>Cached GPU objects</td><td>${window.renderer.metrics.cached}</td></tr><tr><td>Server revision</td><td>${sync.revision}</td></tr><tr><td>Pending changes</td><td>${sync.pending.length}</td></tr></table><p>WebGPU renders basic shapes directly and composites cached textures for text, images, and complex elements. Canvas 2D handles fallback and exports.</p>`);break;
case'help':modal('A few handy shortcuts',`<table class="keyboard-table">${[['Undo / redo','Ctrl Z / Ctrl Shift Z'],['Copy / paste','Ctrl C / Ctrl V'],['Duplicate','Ctrl D'],['Select all','Ctrl A'],['Group / ungroup','Ctrl G / Ctrl Shift G'],['Delete element','Delete or Backspace'],['Move element','Arrow keys · Shift for 10 px'],['Add text','T'],['Add rectangle / ellipse','R / O'],['Edit text','Double click text'],['Zoom','Ctrl + mouse wheel'],['Keep aspect ratio','Shift + resize'],['Bypass snapping','Alt + drag'],['Rotate in 15° steps','Shift + rotate']].map(([a,b])=>`<tr><td>${a}</td><td><kbd>${b}</kbd></td></tr>`).join('')}</table><p>Use ⌘ instead of Ctrl on Mac.</p>`);break;default:if(kind==='overview-page'){switchPage(+arg);closeModal()}}
}
// Central event delegation keeps the editor independent of a UI framework.
document.addEventListener('click',async e=>{const a=e.target.closest('[data-action]');if(a&&!a.closest('.present-overlay')){e.preventDefault();try{await action(a.dataset.action,e)}catch(err){toast(err.message)}return}const layer=e.target.closest('[data-layer]');if(layer){selected=e.shiftKey?[...new Set([...selected,layer.dataset.layer])]:[layer.dataset.layer];draw();toolbar();renderPanel();return}const card=e.target.closest('[data-project]');if(card){openProject(card.dataset.project);return}if(!e.target.closest('.context-menu'))closeContext()});
document.addEventListener('change',e=>{const el=e.target;if(el.dataset.prop)fieldChange(el);if(el.id==='project-title')transaction(()=>doc.name=el.value.trim()||'Untitled design');if(el.id==='page-notes')transaction(()=>pg().notes=el.value);if(el.id==='file-input'){uploadFiles(el.files);el.value=''}if(el.id==='project-filter'||el.id==='folder-filter')renderProjects();if(el.id==='ink-color')state.drawColor=el.value});
document.addEventListener('input',e=>{const el=e.target;if(el.id==='template-search'){search=el.value;renderTemplates()}if(el.id==='project-search')renderProjects();if(el.id==='zoom-slider'){autoFit=false;zoom=+el.value/100;layoutCanvas()}if(el.id==='ink-width'){state.drawWidth=+el.value;$('#ink-width-label').textContent=el.value}});
document.addEventListener('submit',async e=>{e.preventDefault();const f=e.target,data=new FormData(f),submit=$('button[type=submit],button:not([type=button])',f);if(submit)submit.disabled=true;try{if(f.id==='new-design-form'){await createProject(project({name:data.get('name'),width:+data.get('width'),height:+data.get('height')}));closeModal()}if(f.id==='resize-form'){const w=+data.get('width'),h=+data.get('height');transaction(()=>{if(data.get('scale')){for(const p of doc.pages)for(const o of p.objects){const sx=w/doc.width,sy=h/doc.height;o.x*=sx;o.y*=sy;o.w*=sx;o.h*=sy;if(o.fontSize)o.fontSize*=Math.min(sx,sy);if(o.points)o.points=o.points.map(p=>[p[0]*sx,p[1]*sy])}}doc.width=w;doc.height=h});closeModal();fit()}
if(f.id==='crop-form'){transaction(()=>{for(const o of chosen())Object.assign(o,{cropZoom:+data.get('cropZoom'),cropX:+data.get('cropX'),cropY:+data.get('cropY'),fit:data.get('fit')})});closeModal()}
if(f.id==='chart-form'){const values=String(data.get('values')).split(',').map(x=>+x.trim());if(values.some(v=>!Number.isFinite(v)||v<0)||values.length>20)throw Error('Enter up to 20 positive numeric values.');transaction(()=>{one().values=values;one().labels=String(data.get('labels')).split(',').map(x=>x.trim()).slice(0,20)});closeModal()}
if(f.id==='timing-form'){transaction(()=>doc.pages.forEach((p,i)=>p.duration=+data.get('duration-'+i)));closeModal();toolbar()}
if(f.id==='share-form'){await sync.request(`projects/${sync.id}/sharing`,{method:'POST',body:JSON.stringify({email:data.get('email'),role:data.get('role')})});toast('Collaborator access added');share()}
if(f.id==='comment-form'){if(!sync.id)throw Error('Save your design first.');await sync.request(`projects/${sync.id}/comments`,{method:'POST',body:JSON.stringify({page:pg().id,body:data.get('body')})});f.reset();loadComments()}
if(f.id==='version-form'){await sync.settled();await sync.request(`projects/${sync.id}/snapshots`,{method:'POST',body:JSON.stringify({name:data.get('name')})});closeModal();toast('Version saved')}
if(f.id==='project-settings-form'){await sync.request('projects/'+f.dataset.id,{method:'PATCH',body:JSON.stringify({folder:data.get('folder'),starred:!!data.get('starred')})});closeModal();home()}
if(f.id==='export-form'){submit.textContent='Preparing your download…';await exportFile(data.get('format'),+data.get('page'),+data.get('scale'));toast('Your download is ready');closeModal()}
}catch(err){toast(err.message)}finally{if(submit){submit.disabled=false;if(f.id==='export-form')submit.innerHTML=icon('download')+' Download'}}});
document.addEventListener('keydown',e=>{if(presenting)return;if(e.target.matches('input,textarea,select,[contenteditable=true]'))return;if($('#modal').open)return;const cmd=e.ctrlKey||e.metaKey,k=e.key.toLowerCase();let a;if(cmd){a=({z:e.shiftKey?'redo':'undo',y:'redo',c:'copy',v:'paste',d:'duplicate',g:e.shiftKey?'ungroup':'group',s:'save-version'})[k];if(k==='a'){e.preventDefault();selected=pg().objects.filter(o=>!o.hidden).map(o=>o.id);draw();toolbar();return}}else a=({delete:'delete',backspace:'delete',t:'add-text',r:'shape:rect',o:'shape:ellipse','[':'backward',']':'forward'})[k];if(a){e.preventDefault();action(a).catch(err=>toast(err.message));return}if(e.key.startsWith('Arrow')&&selected.length){e.preventDefault();const step=e.shiftKey?10:1;transaction(()=>{for(const o of chosen())if(!o.locked){if(e.key==='ArrowLeft')o.x-=step;if(e.key==='ArrowRight')o.x+=step;if(e.key==='ArrowUp')o.y-=step;if(e.key==='ArrowDown')o.y+=step}})}if(e.key==='Escape'){if(gesture){doc=gesture.before;gesture=null}selected=[];draw();toolbar();closeContext()}});
let draggingPage=null,draggingLayer=null;
document.addEventListener('dragstart',e=>{const p=e.target.closest('[data-page-index]'),l=e.target.closest('[data-layer]');if(p)draggingPage=+p.dataset.pageIndex;if(l)draggingLayer=l.dataset.layer});
document.addEventListener('dragover',e=>{if(e.target.closest('[data-page-index],[data-layer],#upload-zone'))e.preventDefault()});
document.addEventListener('drop',e=>{const p=e.target.closest('[data-page-index]'),l=e.target.closest('[data-layer]');if(p&&draggingPage!==null){e.preventDefault();const dest=+p.dataset.pageIndex;transaction(()=>{const [m]=doc.pages.splice(draggingPage,1);doc.pages.splice(dest,0,m);pageIndex=dest});draggingPage=null}if(l&&draggingLayer){e.preventDefault();transaction(()=>{const from=pg().objects.findIndex(o=>o.id===draggingLayer),to=pg().objects.findIndex(o=>o.id===l.dataset.layer);const [m]=pg().objects.splice(from,1);pg().objects.splice(to,0,m)});draggingLayer=null;renderPanel()}if(e.target.closest('#upload-zone')){e.preventDefault();uploadFiles(e.dataTransfer.files)}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal'))closeModal()});
async function init(){shell();try{user=await sync.init();const explicit=new URLSearchParams(location.search).get('project');let requested=explicit||(LOCAL_MODE?localStorage.getItem('velora-last-project'):null);if(LOCAL_MODE&&requested&&!explicit){try{await sync.local.project(requested)}catch{requested=null;localStorage.removeItem('velora-last-project')}}if(requested){await openProject(requested)}else{doc=await sync.create(doc);setAddress(doc.id);shell();status('All changes saved')}renderPeople()}catch(e){status(e.status===401?'Sign in to save':'Saving unavailable');toast(e.message);if(e.status===401){modal('Welcome to Velora',`<p>Sign in to save designs, upload your media, and collaborate.</p><a class="primary-button full" style="display:flex;text-decoration:none" href="/signin-with-chatgpt?return_to=${encodeURIComponent('/'+location.search)}" target="_top">Sign in with ChatGPT</a><p>You can explore the editor now. Export a design file to keep any unsaved work.</p>${btn('close-modal','Explore the editor','','outline-button full')}`)}}}
window.velora={getDocument:()=>clone(doc),getSelection:()=>[...selected],getRenderer:()=>({backend,...window.renderer.metrics}),newDesign:createProject,exportDesign:exportFile,addText:text=>add(object('text',{text:String(text),x:100,y:100,w:500,h:100,fontSize:48,fontFamily:'Arial',fill:'#283f35'})),addShape:(type,props)=>add(object(type,props)),setPage:i=>switchPage(i),undo:()=>action('undo'),redo:()=>action('redo')};
init();
if(document.modelContext?.registerTool){const lifecycle=new AbortController();const register=t=>Promise.resolve(document.modelContext.registerTool(t,{signal:lifecycle.signal})).catch(()=>{});register({name:'read_design',title:'Read current design',description:'Read the open Velora design, pages, elements, and rendering backend.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:true},execute:()=>({design:clone(doc),renderer:backend})});register({name:'add_text_elements',title:'Add text to the design',description:'Create editable text elements on the currently selected page and queue the change for saving.',inputSchema:{type:'object',properties:{items:{type:'array',maxItems:20,items:{type:'object',properties:{text:{type:'string',maxLength:5000},x:{type:'number'},y:{type:'number'}},required:['text'],additionalProperties:false}}},required:['items'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:async input=>{if(!input||!Array.isArray(input.items)||!input.items.length||input.items.length>20)throw Error('Provide 1–20 text elements');if(input.items.some(x=>typeof x.text!=='string'||x.text.length>5000||[x.x??100,x.y??100].some(v=>!Number.isFinite(v)||Math.abs(v)>100000)))throw Error('Invalid text element');if(!editable())throw Error('Edit access is required');const ids=[];transaction(()=>{for(const item of input.items){const o=object('text',{text:item.text,x:item.x??100,y:item.y??100,w:500,h:100,fontSize:48,fontFamily:'Arial',fill:'#283f35'});pg().objects.push(o);ids.push(o.id)}selected=ids});await new Promise(requestAnimationFrame);return {page:pg().id,elementIds:ids,saved:sync.pending.length===0}}});addEventListener('pagehide',()=>lifecycle.abort(),{once:true})}
